window.LISTENING_REVIEW_1106={"materials":[{"id":"seahorses","slug":"the-seahorses","en":"The Seahorses","zh":"海马","count":22},{"id":"organic","slug":"organic-farming","en":"Organic farming","zh":"有机农业","count":26}],"cards":[{"id":"seahorses-v1","material":"seahorses","en":"crown","zh":"冠；冠状突起","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。区别 head 部位与 crown 结构；/kraʊn/。","sourceId":"6","source":{"en":"A distinctive crown sits on top of their head.","zh":"它们头顶上有一个独特的冠状突起。"},"examples":[{"skill":"听力","en":"The crown is on top of its head.","zh":"冠状突起在它的头顶。"},{"skill":"口语","en":"I noticed a small crown on its head.","zh":"我注意到它头上有一个小冠状突起。"},{"skill":"阅读","en":"The crown helps researchers identify the species.","zh":"这个冠状突起帮助研究人员识别物种。"},{"skill":"写作","en":"The diagram shows a crown above the animal's eyes.","zh":"图中显示该动物眼睛上方有冠状突起。"}],"collocations":[{"en":"a distinctive crown","zh":"独特的冠状突起"}]},{"id":"seahorses-v2","material":"seahorses","en":"shrimp","zh":"虾","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。原错 shrump；/ʃrɪmp/，结尾-mp。","sourceId":"8","source":{"en":"They use their snout to catch food, and their favourite prey is shrimp.","zh":"它们用吻部捕食，最喜欢的猎物是虾。"},"examples":[{"skill":"听力","en":"The fish mainly feed on shrimp.","zh":"这些鱼主要以虾为食。"},{"skill":"口语","en":"I usually order shrimp when I eat seafood.","zh":"我吃海鲜时通常点虾。"},{"skill":"阅读","en":"Small shrimp provide food for many marine animals.","zh":"小虾为许多海洋动物提供食物。"},{"skill":"写作","en":"Protecting coastal habitats can help sustain shrimp populations.","zh":"保护沿海栖息地有助于维持虾的种群。"}],"collocations":[{"en":"feed on shrimp","zh":"以虾为食"}]},{"id":"seahorses-v3","material":"seahorses","en":"salt","zh":"盐；此处指盐度中的盐","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。原错 soule；/sɔːlt/，salt level 盐度。","sourceId":"11","source":{"en":"During this time, the salt level is regulated to help them adjust to life in the ocean.","zh":"在此期间，盐度受到调节，以帮助幼体适应海洋生活。"},"examples":[{"skill":"听力","en":"The salt level is carefully controlled.","zh":"盐度受到仔细控制。"},{"skill":"口语","en":"I try not to add too much salt to my food.","zh":"我尽量不给食物加太多盐。"},{"skill":"阅读","en":"Changes in salt levels affect marine organisms.","zh":"盐度变化影响海洋生物。"},{"skill":"写作","en":"The experiment measured the effect of salt concentration on growth.","zh":"该实验测量了盐浓度对生长的影响。"}],"collocations":[{"en":"salt concentration","zh":"盐浓度"}]},{"id":"seahorses-v4","material":"seahorses","en":"currents","zh":"水流；洋流（复数）","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。原错 carr；/ˈkʌrənts/，current也可作形容词“当前的”。","sourceId":"13","source":{"en":"They can be eaten by predators, or swept away by ocean currents.","zh":"它们可能被捕食者吃掉，也可能被洋流冲走。"},"examples":[{"skill":"听力","en":"Strong currents can carry the young away.","zh":"强劲水流会把幼体带走。"},{"skill":"口语","en":"I wouldn't swim there because of the strong currents.","zh":"我不会去那里游泳，因为水流很强。"},{"skill":"阅读","en":"Ocean currents transport heat around the planet.","zh":"洋流在地球各处输送热量。"},{"skill":"写作","en":"Researchers should consider changes in ocean currents.","zh":"研究人员应考虑洋流的变化。"}],"collocations":[{"en":"ocean currents","zh":"洋流"}]},{"id":"seahorses-v5","material":"seahorses","en":"fishing","zh":"捕鱼；捕捞","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。答案是fishing，不要把研究对象与威胁对象混淆。","sourceId":"14","source":{"en":"Among human-related dangers, fishing poses the greatest threat.","zh":"在人类造成的危险中，捕捞构成最大的威胁。"},"examples":[{"skill":"听力","en":"Fishing is the main human-related threat.","zh":"捕捞是主要的人类相关威胁。"},{"skill":"口语","en":"My uncle enjoys fishing at weekends.","zh":"我叔叔周末喜欢钓鱼。"},{"skill":"阅读","en":"Commercial fishing can affect non-target species.","zh":"商业捕捞可能影响非目标物种。"},{"skill":"写作","en":"Stricter fishing regulations could protect vulnerable marine species.","zh":"更严格的捕捞规定可能保护脆弱的海洋物种。"}],"collocations":[{"en":"commercial fishing","zh":"商业捕捞"}]},{"id":"seahorses-v6","material":"seahorses","en":"stress","zh":"压力；应激","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。圈养语境常译应激；/stres/。","sourceId":"15","source":{"en":"In captivity, many seahorses struggle due to stress, which has been a major cause of low survival rates.","zh":"在圈养环境中，许多海马因应激而难以生存，而应激一直是存活率低的主要原因。"},"examples":[{"skill":"听力","en":"The animals may suffer from stress.","zh":"这些动物可能受到应激影响。"},{"skill":"口语","en":"Listening to music helps me reduce stress.","zh":"听音乐有助于我缓解压力。"},{"skill":"阅读","en":"Stress can influence an animal's behaviour.","zh":"应激会影响动物行为。"},{"skill":"写作","en":"Reducing stress may improve the welfare of captive animals.","zh":"减少应激可能改善圈养动物的福利。"}],"collocations":[{"en":"suffer from stress","zh":"受到压力或应激影响"}]},{"id":"seahorses-v7","material":"seahorses","en":"disease","zh":"疾病","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。原错 deases；/dɪˈziːz/。disease可指疾病总称，diseases指多种疾病。","sourceId":"16","source":{"en":"However, captive breeding programmes have helped lower the risk of disease.","zh":"不过，圈养繁殖计划已帮助降低了疾病风险。"},"examples":[{"skill":"听力","en":"The programme reduces the risk of disease.","zh":"该计划降低疾病风险。"},{"skill":"口语","en":"I read an article about preventing disease.","zh":"我读过一篇预防疾病的文章。"},{"skill":"阅读","en":"The disease spread rapidly through the population.","zh":"这种疾病在种群中迅速传播。"},{"skill":"写作","en":"Early monitoring can reduce the risk of disease outbreaks.","zh":"早期监测可以降低疾病暴发风险。"}],"collocations":[{"en":"the risk of disease","zh":"疾病风险"}]},{"id":"seahorses-v8","material":"seahorses","en":"shallow water","zh":"浅水；浅水区","type":"collocation","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。shallow修饰water，反义deep water。","sourceId":"3","source":{"en":"These environments included stretches of shallow water and different types of vegetation, such as a specific kind of grass.","zh":"这些环境包括大片浅水区以及不同类型的植被，例如某一种草。"},"examples":[{"skill":"听力","en":"The boat stayed in shallow water.","zh":"船停留在浅水区。"},{"skill":"口语","en":"I prefer swimming in shallow water.","zh":"我更喜欢在浅水区游泳。"},{"skill":"阅读","en":"These plants grow in shallow water near the coast.","zh":"这些植物生长在海岸附近的浅水中。"},{"skill":"写作","en":"Coastal development may damage shallow-water habitats.","zh":"沿海开发可能破坏浅水栖息地。"}],"collocations":[{"en":"stretches of shallow water","zh":"大片浅水区"}]},{"id":"seahorses-v9","material":"seahorses","en":"grass","zh":"草；海草语境中的草类","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。grass通常不可数；不在本题写grasses。","sourceId":"3","source":{"en":"These environments included stretches of shallow water and different types of vegetation, such as a specific kind of grass.","zh":"这些环境包括大片浅水区以及不同类型的植被，例如某一种草。"},"examples":[{"skill":"听力","en":"A specific kind of grass grows here.","zh":"这里生长着某一种草。"},{"skill":"口语","en":"I like sitting on the grass in a park.","zh":"我喜欢坐在公园草地上。"},{"skill":"阅读","en":"Dense grass provides shelter for small animals.","zh":"茂密的草为小动物提供庇护。"},{"skill":"写作","en":"The restoration project aims to protect native grass habitats.","zh":"修复项目旨在保护本地草类栖息地。"}],"collocations":[{"en":"a specific kind of grass","zh":"某一种草"}]},{"id":"seahorses-v10","material":"seahorses","en":"bony plates","zh":"骨板","type":"collocation","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。plate不只指盘子；此处指板状骨骼结构，plates为复数。","sourceId":"5","source":{"en":"They swim in an upright position and have skin that stretches over bony plates.","zh":"它们以直立姿态游动，皮肤覆盖在骨板之上。"},"examples":[{"skill":"听力","en":"Its skin covers bony plates.","zh":"它的皮肤覆盖着骨板。"},{"skill":"口语","en":"I learned that seahorses have bony plates.","zh":"我了解到海马有骨板。"},{"skill":"阅读","en":"Bony plates form a protective layer.","zh":"骨板形成保护层。"},{"skill":"写作","en":"The illustration highlights the arrangement of bony plates.","zh":"插图突出了骨板的排列。"}],"collocations":[{"en":"skin that stretches over bony plates","zh":"覆盖骨板的皮肤"}]},{"id":"seahorses-v11","material":"seahorses","en":"habitat","zh":"栖息地","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。/ˈhæbɪtæt/；区别habit习惯。","sourceId":"2","source":{"en":"These geological changes led to the formation of new habitats.","zh":"这些地质变化促成了新栖息地的形成。"},"examples":[{"skill":"听力","en":"New habitats formed after the geological changes.","zh":"地质变化后形成了新栖息地。"},{"skill":"口语","en":"I'd like to see these animals in their natural habitat.","zh":"我想在自然栖息地里看这些动物。"},{"skill":"阅读","en":"Habitat loss threatens many coastal species.","zh":"栖息地丧失威胁着许多沿海物种。"},{"skill":"写作","en":"Governments should protect natural habitats from excessive development.","zh":"政府应保护自然栖息地免受过度开发。"}],"collocations":[{"en":"natural habitat","zh":"自然栖息地"}]},{"id":"seahorses-v12","material":"seahorses","en":"vegetation","zh":"植被","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。不可数总称，不等同于vegetable蔬菜。","sourceId":"3","source":{"en":"These environments included stretches of shallow water and different types of vegetation, such as a specific kind of grass.","zh":"这些环境包括大片浅水区以及不同类型的植被，例如某一种草。"},"examples":[{"skill":"听力","en":"The area has several types of vegetation.","zh":"该区域有几种植被。"},{"skill":"口语","en":"I enjoy places with lots of green vegetation.","zh":"我喜欢绿植茂盛的地方。"},{"skill":"阅读","en":"Coastal vegetation provides shelter for wildlife.","zh":"沿海植被为野生动物提供庇护。"},{"skill":"写作","en":"Restoring vegetation can improve habitat quality.","zh":"恢复植被能改善栖息地质量。"}],"collocations":[{"en":"different types of vegetation","zh":"不同类型的植被"}]},{"id":"seahorses-v13","material":"seahorses","en":"rely on","zh":"依靠；依赖","type":"phrase","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。on为介词；rely on something / someone。","sourceId":"7","source":{"en":"For movement, they rely on their dorsal and pectoral fins.","zh":"在运动方面，它们依靠背鳍和胸鳍。"},"examples":[{"skill":"听力","en":"They rely on their fins for movement.","zh":"它们依靠鳍运动。"},{"skill":"口语","en":"I rely on public transport to get around.","zh":"我靠公共交通出行。"},{"skill":"阅读","en":"Many species rely on healthy coastal ecosystems.","zh":"许多物种依赖健康的沿海生态系统。"},{"skill":"写作","en":"Small communities often rely on fishing for income.","zh":"小型社区往往依靠捕鱼获得收入。"}],"collocations":[{"en":"rely on something for something","zh":"依靠某物获得某物"}]},{"id":"seahorses-v14","material":"seahorses","en":"snout","zh":"吻部；口鼻部","type":"word","stars":3,"priority":false,"origin":"听力材料","note":"重要度：★★★☆☆。/snaʊt/；描述动物身体部位。","sourceId":"8","source":{"en":"They use their snout to catch food, and their favourite prey is shrimp.","zh":"它们用吻部捕食，最喜欢的猎物是虾。"},"examples":[{"skill":"听力","en":"It uses its snout to catch food.","zh":"它用吻部捕食。"},{"skill":"口语","en":"The seahorse's long snout looks unusual.","zh":"海马长长的吻部看起来很特别。"},{"skill":"阅读","en":"The snout is adapted to the animal's feeding behaviour.","zh":"吻部适应了该动物的摄食方式。"},{"skill":"写作","en":"The diagram shows the position of the snout.","zh":"示意图显示了吻部的位置。"}],"collocations":[{"en":"use its snout to catch food","zh":"用吻部捕食"}]},{"id":"seahorses-v15","material":"seahorses","en":"prey","zh":"猎物","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。常作不可数集合名词；区别predator捕食者。","sourceId":"8","source":{"en":"They use their snout to catch food, and their favourite prey is shrimp.","zh":"它们用吻部捕食，最喜欢的猎物是虾。"},"examples":[{"skill":"听力","en":"Shrimp are a common type of prey.","zh":"虾是一种常见猎物。"},{"skill":"口语","en":"I watched a bird catch its prey.","zh":"我看过鸟捕捉猎物。"},{"skill":"阅读","en":"Predators depend on the availability of prey.","zh":"捕食者依赖猎物的可获得性。"},{"skill":"写作","en":"A decline in prey can disrupt the food chain.","zh":"猎物减少可能扰乱食物链。"}],"collocations":[{"en":"catch prey","zh":"捕捉猎物"}]},{"id":"seahorses-v16","material":"seahorses","en":"pouch","zh":"袋；育儿袋","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。/paʊtʃ/；male's pouch是雄海马的育儿袋。","sourceId":"9","source":{"en":"In seahorse reproduction, the female places her eggs into the male's pouch.","zh":"在海马繁殖过程中，雌海马会把卵放入雄海马的育儿袋。"},"examples":[{"skill":"听力","en":"The eggs are placed in the male's pouch.","zh":"卵被放入雄海马的育儿袋。"},{"skill":"口语","en":"I was surprised that the male has a pouch.","zh":"雄性有育儿袋让我很惊讶。"},{"skill":"阅读","en":"The young develop inside a protective pouch.","zh":"幼体在保护性的育儿袋内发育。"},{"skill":"写作","en":"The pouch provides a controlled environment for early development.","zh":"育儿袋为早期发育提供受控环境。"}],"collocations":[{"en":"the male's pouch","zh":"雄性的育儿袋"}]},{"id":"seahorses-v17","material":"seahorses","en":"hatch","zh":"孵化；破壳","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。once they hatch 一旦它们孵化。","sourceId":"10","source":{"en":"Once they hatch, the young remain in the pouch for a period.","zh":"一旦孵化，幼体还会在育儿袋里停留一段时间。"},"examples":[{"skill":"听力","en":"The eggs hatch after a period of development.","zh":"经过一段发育时间，卵孵化。"},{"skill":"口语","en":"I'd love to see baby turtles hatch.","zh":"我很想看小海龟孵化。"},{"skill":"阅读","en":"Temperature can affect when eggs hatch.","zh":"温度会影响卵何时孵化。"},{"skill":"写作","en":"The study recorded the proportion of eggs that hatched.","zh":"该研究记录了孵化卵的比例。"}],"collocations":[{"en":"once they hatch","zh":"一旦孵化"}]},{"id":"seahorses-v18","material":"seahorses","en":"adjust to","zh":"适应","type":"phrase","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。to为介词：adjust to life / doing。","sourceId":"11","source":{"en":"During this time, the salt level is regulated to help them adjust to life in the ocean.","zh":"在此期间，盐度受到调节，以帮助幼体适应海洋生活。"},"examples":[{"skill":"听力","en":"They need to adjust to life in the ocean.","zh":"它们需要适应海洋生活。"},{"skill":"口语","en":"It took me a week to adjust to my new routine.","zh":"我花了一周适应新的日常安排。"},{"skill":"阅读","en":"Young animals must adjust to changing conditions.","zh":"幼小动物必须适应变化的条件。"},{"skill":"写作","en":"Gradual exposure may help organisms adjust to a new environment.","zh":"逐步接触可能帮助生物适应新环境。"}],"collocations":[{"en":"adjust to a new environment","zh":"适应新环境"}]},{"id":"seahorses-v19","material":"seahorses","en":"sweep away","zh":"冲走；卷走","type":"phrase","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。原稿被动式be swept away；sweep→swept→swept。","sourceId":"13","source":{"en":"They can be eaten by predators, or swept away by ocean currents.","zh":"它们可能被捕食者吃掉，也可能被洋流冲走。"},"examples":[{"skill":"听力","en":"Small animals can be swept away by the current.","zh":"小动物可能被水流冲走。"},{"skill":"口语","en":"I saw the waves sweep away a small sandcastle.","zh":"我看见海浪冲走了一座小沙堡。"},{"skill":"阅读","en":"Floodwater swept away the loose soil.","zh":"洪水冲走了松散土壤。"},{"skill":"写作","en":"Vegetation can reduce the amount of soil swept away by floods.","zh":"植被可以减少被洪水冲走的土壤量。"}],"collocations":[{"en":"be swept away by currents","zh":"被水流冲走"}]},{"id":"seahorses-v20","material":"seahorses","en":"pose a threat to","zh":"对……构成威胁","type":"collocation","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。pose不是摆姿势；pose a threat表示造成威胁。","sourceId":"14","source":{"en":"Among human-related dangers, fishing poses the greatest threat.","zh":"在人类造成的危险中，捕捞构成最大的威胁。"},"examples":[{"skill":"听力","en":"Fishing poses a threat to these animals.","zh":"捕捞对这些动物构成威胁。"},{"skill":"口语","en":"I think plastic waste poses a threat to sea life.","zh":"我认为塑料垃圾威胁海洋生命。"},{"skill":"阅读","en":"Rising temperatures pose a threat to sensitive species.","zh":"气温上升对敏感物种构成威胁。"},{"skill":"写作","en":"Habitat destruction poses a serious threat to biodiversity.","zh":"栖息地破坏严重威胁生物多样性。"}],"collocations":[{"en":"pose the greatest threat","zh":"构成最大威胁"}]},{"id":"seahorses-v21","material":"seahorses","en":"in captivity","zh":"在圈养环境中","type":"phrase","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。区别in the wild在野外；captive为形容词。","sourceId":"15","source":{"en":"In captivity, many seahorses struggle due to stress, which has been a major cause of low survival rates.","zh":"在圈养环境中，许多海马因应激而难以生存，而应激一直是存活率低的主要原因。"},"examples":[{"skill":"听力","en":"Survival rates are low in captivity.","zh":"圈养条件下存活率较低。"},{"skill":"口语","en":"I prefer seeing animals in the wild rather than in captivity.","zh":"我更喜欢在野外而非圈养环境里看动物。"},{"skill":"阅读","en":"Some species behave differently in captivity.","zh":"某些物种在圈养条件下表现出不同行为。"},{"skill":"写作","en":"Research on animals in captivity requires careful welfare standards.","zh":"对圈养动物的研究需要严格的福利标准。"}],"collocations":[{"en":"breed in captivity","zh":"在圈养条件下繁殖"}]},{"id":"seahorses-v22","material":"seahorses","en":"captive breeding programmes","zh":"圈养繁殖计划","type":"collocation","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。帮助降低风险不等于完全消除风险。","sourceId":"16","source":{"en":"However, captive breeding programmes have helped lower the risk of disease.","zh":"不过，圈养繁殖计划已帮助降低了疾病风险。"},"examples":[{"skill":"听力","en":"Captive breeding programmes can support conservation.","zh":"圈养繁殖计划能支持保护工作。"},{"skill":"口语","en":"I learned about captive breeding programmes at a wildlife centre.","zh":"我在野生动物中心了解了圈养繁殖计划。"},{"skill":"阅读","en":"Captive breeding programmes require long-term monitoring.","zh":"圈养繁殖计划需要长期监测。"},{"skill":"写作","en":"Well-managed captive breeding programmes may support species recovery.","zh":"管理良好的圈养繁殖计划可能促进物种恢复。"}],"collocations":[{"en":"lower the risk of disease","zh":"降低疾病风险"}]},{"id":"organic-v1","material":"organic","en":"sustainable","zh":"可持续的","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。不是“暂时有效”；可修饰farming / development。","sourceId":"7","source":{"en":"To begin with, organic farming is labelled as sustainable because it can protect the environment and maintain biological diversity.","zh":"首先，有机农业被称为可持续的，因为它能够保护环境并维持生物多样性。"},"examples":[{"skill":"听力","en":"The report describes the method as sustainable.","zh":"报告将这种方法描述为可持续的。"},{"skill":"口语","en":"I'd like to live in a more sustainable way.","zh":"我想以更可持续的方式生活。"},{"skill":"阅读","en":"Sustainable systems aim to preserve resources for the future.","zh":"可持续体系旨在为未来保存资源。"},{"skill":"写作","en":"Investment in sustainable agriculture should consider both yields and environmental impacts.","zh":"对可持续农业的投资应兼顾产量和环境影响。"}],"collocations":[{"en":"sustainable farming practices","zh":"可持续农业实践"}]},{"id":"organic-v2","material":"organic","en":"sales","zh":"销售额；销量","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。原来填foods；题目要商业指标，sales通常用复数形式。","sourceId":"10","source":{"en":"So this type of farming is expected to contribute to an increase in sales for grocery stores globally.","zh":"因此，这种农业方式预计会促进全球食品杂货店销售额的增长。"},"examples":[{"skill":"听力","en":"Sales increased by twenty per cent.","zh":"销售额增长了20%。"},{"skill":"口语","en":"I used to help a team improve product sales.","zh":"我曾帮助团队提升产品销售。"},{"skill":"阅读","en":"The company reported a slowdown in sales growth.","zh":"该公司报告销售增长放缓。"},{"skill":"写作","en":"Higher consumer demand may lead to an increase in sales.","zh":"更高的消费者需求可能带来销售额增长。"}],"collocations":[{"en":"an increase in sales","zh":"销售额的增长"}]},{"id":"organic-v3","material":"organic","en":"energy","zh":"能源；能量","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。不可数；要听清节省什么与生产什么的区别。","sourceId":"12","source":{"en":"This is primarily due to the fact that organic farming eliminates the need for synthetic fertilizers, which require substantial energy for production.","zh":"这主要是因为有机农业免去了使用合成化肥的需要，而生产合成化肥需要大量能源。"},"examples":[{"skill":"听力","en":"Producing these materials requires a lot of energy.","zh":"生产这些材料需要大量能源。"},{"skill":"口语","en":"I try to save energy by switching off unused lights.","zh":"我会关掉不用的灯来节约能源。"},{"skill":"阅读","en":"Energy use varies between production systems.","zh":"不同生产体系的能源使用量存在差异。"},{"skill":"写作","en":"Improved technology can reduce energy consumption.","zh":"技术改进可以减少能源消耗。"}],"collocations":[{"en":"reduce energy consumption","zh":"减少能源消耗"}]},{"id":"organic-v4","material":"organic","en":"insects","zh":"昆虫（复数）","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。原漏答；control insects对应reduce the number of insects。","sourceId":"15","source":{"en":"Importantly, organic methods have the potential to effectively control insects that pose threats to crops, unlike artificial fertilizers which may not have the same level of efficacy.","zh":"有机方法有潜力有效控制威胁作物的昆虫；讲稿将其与可能没有同样效力的人造化肥作了对比。"},"examples":[{"skill":"听力","en":"Some insects may damage crops.","zh":"某些昆虫可能损害作物。"},{"skill":"口语","en":"I don't like insects flying around my food.","zh":"我不喜欢昆虫在食物周围飞。"},{"skill":"阅读","en":"Not all insects are harmful to agriculture.","zh":"并非所有昆虫都对农业有害。"},{"skill":"写作","en":"Farm management should protect beneficial insects.","zh":"农场管理应保护有益昆虫。"}],"collocations":[{"en":"control insects that threaten crops","zh":"控制威胁作物的昆虫"}]},{"id":"organic-v5","material":"organic","en":"potatoes","zh":"土豆（复数）","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。原错potato；potato→potatoes；/pəˈteɪtəʊz/。","sourceId":"20","source":{"en":"This past winter, due to extreme weather condition, the production of potatoes in the north of our country had gone down by 40%.","zh":"刚过去的冬天，由于极端天气，我国北部的土豆产量下降了40%。"},"examples":[{"skill":"听力","en":"The production of potatoes fell last winter.","zh":"去年冬天土豆产量下降了。"},{"skill":"口语","en":"I often cook potatoes with other vegetables.","zh":"我经常把土豆和其他蔬菜一起做。"},{"skill":"阅读","en":"Potatoes are grown in a wide range of climates.","zh":"土豆在多种气候条件下种植。"},{"skill":"写作","en":"The chart compares annual production of potatoes and tomatoes.","zh":"该图比较了土豆与番茄的年产量。"}],"collocations":[{"en":"the production of potatoes","zh":"土豆产量"}]},{"id":"organic-v6","material":"organic","en":"grass","zh":"草；牧草","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。不可数；organic grass指有机方式生产的草。","sourceId":"25","source":{"en":"Despite weather challenges, the production of organic grass has not changed much over the years due to the implementation of various strategies.","zh":"尽管有天气带来的挑战，由于采取了多种策略，有机草的产量多年来没有太大变化。"},"examples":[{"skill":"听力","en":"Organic grass production has remained stable.","zh":"有机牧草产量保持稳定。"},{"skill":"口语","en":"I like walking on grass when the weather is nice.","zh":"天气好时我喜欢在草地上走。"},{"skill":"阅读","en":"Grass provides feed for many farm animals.","zh":"草为许多农场动物提供饲料。"},{"skill":"写作","en":"Grass production depends partly on local growing conditions.","zh":"牧草产量部分取决于当地生长条件。"}],"collocations":[{"en":"organic grass production","zh":"有机牧草生产"}]},{"id":"organic-v7","material":"organic","en":"yield","zh":"产量；产生","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。题干yield名词对应production；yielded more crops作动词。","sourceId":"28","source":{"en":"One notable development was the growing production of crops through organic farming practices, especially when compared to the early days when there was a food crisis.","zh":"一个显著的发展是，通过有机农业方法实现的作物产量增长，尤其是与早期发生粮食危机时相比。"},"examples":[{"skill":"听力","en":"The yield went down by forty per cent.","zh":"产量下降了40%。"},{"skill":"口语","en":"I learned that weather can affect crop yields.","zh":"我了解到天气会影响作物产量。"},{"skill":"阅读","en":"The new system yielded more crops in the trial.","zh":"新体系在试验中产出了更多作物。"},{"skill":"写作","en":"Farmers need to balance crop yields with long-term soil health.","zh":"农民需要平衡作物产量与长期土壤健康。"}],"collocations":[{"en":"crop yields","zh":"作物产量"}]},{"id":"organic-v8","material":"organic","en":"go down by","zh":"下降了……幅度","type":"phrase","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。by是变化量；go down to是终值。","sourceId":"20","source":{"en":"This past winter, due to extreme weather condition, the production of potatoes in the north of our country had gone down by 40%.","zh":"刚过去的冬天，由于极端天气，我国北部的土豆产量下降了40%。"},"examples":[{"skill":"听力","en":"Production went down by forty per cent.","zh":"产量下降了40%。"},{"skill":"口语","en":"My monthly spending went down by about ten per cent.","zh":"我每月的支出下降了约10%。"},{"skill":"阅读","en":"The proportion went down by five percentage points.","zh":"该比例下降了五个百分点。"},{"skill":"写作","en":"Output went down by 20%, from 100 tonnes to 80 tonnes.","zh":"产出从100吨降至80吨，下降了20%。"}],"collocations":[{"en":"go down to a given level","zh":"下降到某个水平"}]},{"id":"organic-v9","material":"organic","en":"percentage points","zh":"百分点","type":"collocation","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。30%→20%相差10个百分点；相对增速降幅约33.3%，不要混用。","sourceId":"24","source":{"en":"But this year, it's only gone up by 20%.","zh":"但今年，销售额只增长了20%。"},"examples":[{"skill":"听力","en":"The rate fell by ten percentage points.","zh":"该比率下降了10个百分点。"},{"skill":"口语","en":"I check whether a report means per cent or percentage points.","zh":"我会核对报告指的是百分比还是百分点。"},{"skill":"阅读","en":"A rise from 20% to 30% is an increase of ten percentage points.","zh":"从20%升至30%是增加十个百分点。"},{"skill":"写作","en":"The sales growth rate fell by ten percentage points, from 30% to 20%.","zh":"销售增长率从30%降至20%，下降十个百分点。"}],"collocations":[{"en":"a fall of ten percentage points","zh":"下降十个百分点"}]},{"id":"organic-v10","material":"organic","en":"remain the same","zh":"保持不变","type":"phrase","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。对应has not changed much；是近义概括，并非逐字完全相同。","sourceId":"25","source":{"en":"Despite weather challenges, the production of organic grass has not changed much over the years due to the implementation of various strategies.","zh":"尽管有天气带来的挑战，由于采取了多种策略，有机草的产量多年来没有太大变化。"},"examples":[{"skill":"听力","en":"The production level remained the same.","zh":"产量水平保持不变。"},{"skill":"口语","en":"My study routine has remained the same this week.","zh":"我本周的学习安排保持不变。"},{"skill":"阅读","en":"The total remained the same despite changes in individual categories.","zh":"尽管各类别变化，总量保持不变。"},{"skill":"写作","en":"The figure remained the same throughout the period.","zh":"该数值在整个时期内保持不变。"}],"collocations":[{"en":"has not changed much","zh":"没有太大变化"}]},{"id":"organic-v11","material":"organic","en":"synthetic fertilizers","zh":"合成化肥","type":"collocation","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。按此前音频核对；fertilizers≠pesticides。","sourceId":"12","source":{"en":"This is primarily due to the fact that organic farming eliminates the need for synthetic fertilizers, which require substantial energy for production.","zh":"这主要是因为有机农业免去了使用合成化肥的需要，而生产合成化肥需要大量能源。"},"examples":[{"skill":"听力","en":"Synthetic fertilizers require energy for production.","zh":"合成化肥的生产需要能源。"},{"skill":"口语","en":"I learned the difference between synthetic fertilizers and pesticides.","zh":"我学到了合成化肥和农药的区别。"},{"skill":"阅读","en":"The study measured energy used in manufacturing synthetic fertilizers.","zh":"该研究测量了制造合成化肥所用的能源。"},{"skill":"写作","en":"Reducing reliance on synthetic fertilizers may change agricultural energy demand.","zh":"减少对合成化肥的依赖可能改变农业能源需求。"}],"collocations":[{"en":"the production of synthetic fertilizers","zh":"合成化肥的生产"}]},{"id":"organic-v12","material":"organic","en":"soil fertility","zh":"土壤肥力","type":"collocation","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。fertility此处不是人的生育能力。","sourceId":"13","source":{"en":"In organic farming, soil fertility is maintained through the recycling of organic residues and nutrients produced on the farm.","zh":"在有机农业中，土壤肥力通过回收利用农场产生的有机残余物和养分来维持。"},"examples":[{"skill":"听力","en":"Recycling nutrients helps maintain soil fertility.","zh":"循环利用养分有助于维持土壤肥力。"},{"skill":"口语","en":"I didn't know much about soil fertility before this lesson.","zh":"上这节课前，我对土壤肥力了解不多。"},{"skill":"阅读","en":"Soil fertility affects the growth of crops.","zh":"土壤肥力影响作物生长。"},{"skill":"写作","en":"Long-term agricultural planning should protect soil fertility.","zh":"长期农业规划应保护土壤肥力。"}],"collocations":[{"en":"maintain soil fertility","zh":"维持土壤肥力"}]},{"id":"organic-v13","material":"organic","en":"contribute to","zh":"促成；有助于","type":"phrase","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。to为介词，后接名词或动名词。","sourceId":"10","source":{"en":"So this type of farming is expected to contribute to an increase in sales for grocery stores globally.","zh":"因此，这种农业方式预计会促进全球食品杂货店销售额的增长。"},"examples":[{"skill":"听力","en":"The campaign contributed to an increase in sales.","zh":"该活动促进了销售额增长。"},{"skill":"口语","en":"Regular practice contributes to my confidence.","zh":"经常练习有助于增强我的信心。"},{"skill":"阅读","en":"Several factors contributed to the change.","zh":"多种因素促成了这一变化。"},{"skill":"写作","en":"Better information can contribute to more informed consumer choices.","zh":"更充分的信息有助于消费者作出更知情的选择。"}],"collocations":[{"en":"contribute to an increase in something","zh":"促成某方面的增长"}]},{"id":"organic-v14","material":"organic","en":"consumer demand","zh":"消费者需求","type":"collocation","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。demand of the market→消费者需求；Q40决定因素。","sourceId":"39","source":{"en":"The good thing is that the scale of organic farming can be mostly determined by the demand of the market.","zh":"有利的一点是，有机农业的规模在很大程度上可以由市场需求决定。"},"examples":[{"skill":"听力","en":"Consumer demand determines the scale of production.","zh":"消费者需求决定生产规模。"},{"skill":"口语","en":"I think consumer demand can change quite quickly.","zh":"我觉得消费者需求变化会很快。"},{"skill":"阅读","en":"Companies adjust supply in response to consumer demand.","zh":"企业会根据消费者需求调整供应。"},{"skill":"写作","en":"Growing consumer demand may encourage investment in organic products.","zh":"消费者需求增长可能促进对有机产品的投资。"}],"collocations":[{"en":"meet consumer demand","zh":"满足消费者需求"}]},{"id":"organic-v15","material":"organic","en":"be reluctant to","zh":"不愿意；不情愿做","type":"phrase","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。Q38 B为被否定的看法；reluctant对应unwilling。","sourceId":"30","source":{"en":"Unlike the common perception that farmers were unwilling to accept organic farming, they actually showed interest in its potential benefits.","zh":"与农民不愿接受有机农业这一普遍看法不同，他们实际上对其潜在好处表现出了兴趣。"},"examples":[{"skill":"听力","en":"The farmers were not reluctant to try the method.","zh":"农民并非不愿尝试这种方法。"},{"skill":"口语","en":"I was reluctant to speak English at first.","zh":"一开始我不太愿意说英语。"},{"skill":"阅读","en":"Some users are reluctant to adopt unfamiliar technology.","zh":"一些用户不愿采用不熟悉的技术。"},{"skill":"写作","en":"People may be reluctant to pay more without clear benefits.","zh":"如果好处不明确，人们可能不愿多花钱。"}],"collocations":[{"en":"be unwilling to accept something","zh":"不愿接受某事物"}]},{"id":"organic-v16","material":"organic","en":"encounter difficulties in","zh":"在……方面遇到困难","type":"phrase","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。in后用doing；Q38否定实施顺利的C。","sourceId":"32","source":{"en":"They encountered difficulties in effectively applying the prescribed instructions, which hindered their ability to fully embrace organic farming practices.","zh":"他们在有效执行规定指导时遇到了困难，这阻碍了他们全面采用有机农业方法。"},"examples":[{"skill":"听力","en":"They encountered difficulties in following the instructions.","zh":"他们在执行指导时遇到了困难。"},{"skill":"口语","en":"I sometimes encounter difficulties in understanding long sentences.","zh":"我有时在理解长句时遇到困难。"},{"skill":"阅读","en":"The team encountered difficulties in implementing the plan.","zh":"团队在实施计划时遇到了困难。"},{"skill":"写作","en":"Small farms may encounter difficulties in adopting new techniques.","zh":"小农场在采用新技术时可能遇到困难。"}],"collocations":[{"en":"encounter difficulties in applying instructions","zh":"在执行指导时遇到困难"}]},{"id":"organic-v17","material":"organic","en":"hinder","zh":"阻碍","type":"word","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。hinder their ability to do阻碍其做某事的能力。","sourceId":"32","source":{"en":"They encountered difficulties in effectively applying the prescribed instructions, which hindered their ability to fully embrace organic farming practices.","zh":"他们在有效执行规定指导时遇到了困难，这阻碍了他们全面采用有机农业方法。"},"examples":[{"skill":"听力","en":"The problem hindered their ability to use the method.","zh":"这一问题阻碍了他们使用该方法。"},{"skill":"口语","en":"A lack of sleep can hinder my concentration.","zh":"睡眠不足会妨碍我集中注意力。"},{"skill":"阅读","en":"Limited resources hindered the adoption of the system.","zh":"资源有限阻碍了该体系的采用。"},{"skill":"写作","en":"Insufficient training may hinder the effective implementation of new policies.","zh":"培训不足可能阻碍新政策的有效实施。"}],"collocations":[{"en":"hinder the ability to do something","zh":"阻碍做某事的能力"}]},{"id":"organic-v18","material":"organic","en":"provide a sanctuary for wildlife","zh":"为野生动物提供庇护","type":"collocation","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。Q39答案依据；sanctuary /ˈsæŋktʃuəri/。","sourceId":"34","source":{"en":"The review examined the global implications of organic methods, concluding that such practices, which avoid synthetic chemicals, provide a sanctuary for wildlife, thereby enhancing biodiversity and ecological health.","zh":"该综述考察了有机方法的全球影响，并得出结论：这些避免使用合成化学品的方法为野生动物提供庇护，从而改善生物多样性和生态健康。"},"examples":[{"skill":"听力","en":"The area provides a sanctuary for wildlife.","zh":"该地区为野生动物提供庇护。"},{"skill":"口语","en":"I'd like to visit a place that provides a sanctuary for wildlife.","zh":"我想去一个为野生动物提供庇护的地方。"},{"skill":"阅读","en":"Protected wetlands can provide a sanctuary for wildlife.","zh":"受保护的湿地能为野生动物提供庇护。"},{"skill":"写作","en":"Land-use policies should preserve areas that provide a sanctuary for wildlife.","zh":"土地使用政策应保留为野生动物提供庇护的区域。"}],"collocations":[{"en":"a wildlife sanctuary","zh":"野生动物保护区"}]},{"id":"organic-v19","material":"organic","en":"biological diversity","zh":"生物多样性","type":"collocation","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。与biodiversity同义。","sourceId":"7","source":{"en":"To begin with, organic farming is labelled as sustainable because it can protect the environment and maintain biological diversity.","zh":"首先，有机农业被称为可持续的，因为它能够保护环境并维持生物多样性。"},"examples":[{"skill":"听力","en":"The system aims to maintain biological diversity.","zh":"该体系旨在维持生物多样性。"},{"skill":"口语","en":"I find biological diversity fascinating.","zh":"我觉得生物多样性很有趣。"},{"skill":"阅读","en":"Biological diversity includes variation among species.","zh":"生物多样性包含物种之间的差异。"},{"skill":"写作","en":"Protecting biological diversity requires attention to entire ecosystems.","zh":"保护生物多样性需要关注整个生态系统。"}],"collocations":[{"en":"maintain biological diversity","zh":"维持生物多样性"}]},{"id":"organic-v20","material":"organic","en":"adopt","zh":"采用；采纳","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。区别adapt适应；adopt a method / adapt to conditions。","sourceId":"29","source":{"en":"This positive outcome encouraged farmers to explore and adopt organic methods.","zh":"这一积极结果鼓励农民探索和采用有机方法。"},"examples":[{"skill":"听力","en":"Farmers began to adopt organic methods.","zh":"农民开始采用有机方法。"},{"skill":"口语","en":"I adopted a simpler study routine.","zh":"我采用了更简单的学习安排。"},{"skill":"阅读","en":"Businesses adopted new techniques to improve efficiency.","zh":"企业采用新技术来提高效率。"},{"skill":"写作","en":"Governments should support farmers who adopt sustainable practices.","zh":"政府应支持采用可持续方法的农民。"}],"collocations":[{"en":"adopt organic methods","zh":"采用有机方法"}]},{"id":"organic-v21","material":"organic","en":"despite","zh":"尽管","type":"word","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。介词，后接名词/动名词；不能直接接完整句。","sourceId":"31","source":{"en":"However, despite their enthusiasm, farmers faced challenges in successfully implementing organic farming techniques.","zh":"然而，尽管农民热情很高，他们在成功实施有机农业技术时仍面临挑战。"},"examples":[{"skill":"听力","en":"Despite their enthusiasm, they faced difficulties.","zh":"尽管很有热情，他们仍遇到了困难。"},{"skill":"口语","en":"I went for a walk despite the rain.","zh":"尽管下雨，我还是去散步了。"},{"skill":"阅读","en":"Production remained stable despite weather challenges.","zh":"尽管有天气挑战，产量仍保持稳定。"},{"skill":"写作","en":"Despite increasing demand, some producers face financial difficulties.","zh":"尽管需求增长，一些生产者仍面临财务困难。"}],"collocations":[{"en":"despite their enthusiasm","zh":"尽管他们热情很高"}]},{"id":"organic-v22","material":"organic","en":"be determined by","zh":"由……决定","type":"phrase","stars":5,"priority":true,"origin":"听力材料","note":"重要度：★★★★★。被动，by后是决定因素，不是被决定的结果。","sourceId":"39","source":{"en":"The good thing is that the scale of organic farming can be mostly determined by the demand of the market.","zh":"有利的一点是，有机农业的规模在很大程度上可以由市场需求决定。"},"examples":[{"skill":"听力","en":"The scale is determined by market demand.","zh":"规模由市场需求决定。"},{"skill":"口语","en":"My weekend plans are often determined by the weather.","zh":"我的周末计划常常由天气决定。"},{"skill":"阅读","en":"Prices are partly determined by supply and demand.","zh":"价格部分由供需决定。"},{"skill":"写作","en":"The success of a policy may be determined by how it is implemented.","zh":"政策的成效可能取决于其实施方式。"}],"collocations":[{"en":"be determined by market demand","zh":"由市场需求决定"}]},{"id":"organic-v23","material":"organic","en":"willingness to pay","zh":"付费意愿","type":"collocation","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。作名词搭配，原稿willingness-to-pay；区别ability to pay支付能力。","sourceId":"38","source":{"en":"Consumers' knowledge about organic food is increasing, so are their attitudes, preferences and willingness-to-pay for organic products.","zh":"消费者对有机食品的了解正在增加；讲稿也说，他们的态度、偏好和付费意愿在增强。"},"examples":[{"skill":"听力","en":"Consumers showed a greater willingness to pay.","zh":"消费者表现出更高的付费意愿。"},{"skill":"口语","en":"My willingness to pay depends on the product's quality.","zh":"我的付费意愿取决于产品质量。"},{"skill":"阅读","en":"The survey measured consumers' willingness to pay for organic food.","zh":"该调查衡量消费者为有机食品付费的意愿。"},{"skill":"写作","en":"Clear product information may affect consumers' willingness to pay.","zh":"清晰的产品信息可能影响消费者的付费意愿。"}],"collocations":[{"en":"consumers' willingness to pay","zh":"消费者的付费意愿"}]},{"id":"organic-v24","material":"organic","en":"conventional farming","zh":"传统农业；常规农业","type":"collocation","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。本稿比较对象；不要把conventional理解为会议相关。","sourceId":"11","source":{"en":"Most studies suggest that organic farming uses significantly less energy than conventional one.","zh":"大多数研究表明，有机农业使用的能源明显少于传统农业。"},"examples":[{"skill":"听力","en":"Organic farming was compared with conventional farming.","zh":"有机农业与常规农业进行了比较。"},{"skill":"口语","en":"I'd like to know how conventional farming works.","zh":"我想知道常规农业如何运作。"},{"skill":"阅读","en":"The two studies used different definitions of conventional farming.","zh":"两项研究对常规农业采用了不同定义。"},{"skill":"写作","en":"Comparisons with conventional farming should account for crop type and location.","zh":"与常规农业比较时应考虑作物类型和地点。"}],"collocations":[{"en":"compared to conventional farming","zh":"与常规农业相比"}]},{"id":"organic-v25","material":"organic","en":"feed on","zh":"以……为食","type":"phrase","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。on为介词，区别feed animals喂动物。","sourceId":"17","source":{"en":"Ladybugs are natural predators of aphids and feed on them, effectively reducing their population.","zh":"瓢虫是蚜虫的天敌，以蚜虫为食，从而有效减少其数量。"},"examples":[{"skill":"听力","en":"Ladybugs feed on aphids.","zh":"瓢虫以蚜虫为食。"},{"skill":"口语","en":"I learned that some insects feed on other insects.","zh":"我了解到一些昆虫以其他昆虫为食。"},{"skill":"阅读","en":"Predators feed on organisms lower in the food chain.","zh":"捕食者以食物链较低层级的生物为食。"},{"skill":"写作","en":"Introducing species that feed on pests requires careful assessment.","zh":"引入以害虫为食的物种需要仔细评估。"}],"collocations":[{"en":"natural predators of aphids","zh":"蚜虫的天敌"}]},{"id":"organic-v26","material":"organic","en":"take steps to","zh":"采取措施做……","type":"phrase","stars":4,"priority":false,"origin":"听力材料","note":"重要度：★★★★☆。固定表达take steps to improve / protect。","sourceId":"36","source":{"en":"Subsequently, many took steps to improve their agricultural practices, integrating organic farming principles to support both the environment and local economy.","zh":"随后，许多国家采取措施改进农业实践，将有机农业原则融入其中，以支持环境和当地经济。"},"examples":[{"skill":"听力","en":"Several countries took steps to improve farming practices.","zh":"几个国家采取措施改进农业实践。"},{"skill":"口语","en":"I took steps to improve my sleep routine.","zh":"我采取措施改善作息。"},{"skill":"阅读","en":"The organisation took steps to address the problem.","zh":"该组织采取措施解决问题。"},{"skill":"写作","en":"Authorities should take steps to protect sensitive habitats.","zh":"有关部门应采取措施保护敏感栖息地。"}],"collocations":[{"en":"take steps to improve something","zh":"采取措施改进某事物"}]}],"sentences":{"seahorses":[{"id":"seahorses-s1","section":"演化与栖息地","en":"The seahorse might have developed as a result of movements in the Earth's crust.","zh":"海马可能是由于地壳运动而演化形成的。","note":"主干 The seahorse might have developed；might have + 过去分词表示对过去的推测；as a result of 后接原因名词。crust 在这里指地壳。","listen":"先抓 might have developed，再把 as a result of 后面的内容听作原因。","questions":[]},{"id":"seahorses-s2","section":"演化与栖息地","en":"These geological changes led to the formation of new habitats.","zh":"这些地质变化促成了新栖息地的形成。","note":"主干 changes led to the formation；these 回指地壳运动；lead to 的 to 是介词，后接名词或动名词。","listen":"led to 标记因果；formation 和 habitats 是接下来描述环境的铺垫。","questions":[]},{"id":"seahorses-s3","section":"演化与栖息地","en":"These environments included stretches of shallow water and different types of vegetation, such as a specific kind of grass.","zh":"这些环境包括大片浅水区以及不同类型的植被，例如某一种草。","note":"included 后并列两项：stretches of shallow water / different types of vegetation；such as 引出植被的例子。shallow 修饰 water；grass 是不可数名词。","listen":"Q31 先预测形容词，Q32 预测植物名词。听到 such as 后等待例子，不要停留在 vegetation。","questions":[31,32]},{"id":"seahorses-s4","section":"身体特征","en":"Seahorses have several unique characteristics.","zh":"海马有几种独特的特征。","note":"主谓宾：Seahorses / have / several unique characteristics；这是从栖息地转入身体特征的总起句。","listen":"characteristics 是话题切换路标，接下来连续列举特征。","questions":[]},{"id":"seahorses-s5","section":"身体特征","en":"They swim in an upright position and have skin that stretches over bony plates.","zh":"它们以直立姿态游动，皮肤覆盖在骨板之上。","note":"They 是两个并列谓语 swim / have 的共同主语；that stretches over bony plates 是修饰 skin 的定语从句。bony 修饰 plates。","listen":"Q33 在 bony 后；注意 plates 的复数尾音 /s/。stretches over 在本句表示覆盖。","questions":[33]},{"id":"seahorses-s6","section":"身体特征","en":"A distinctive crown sits on top of their head.","zh":"它们头顶上有一个独特的冠状突起。","note":"主语 A distinctive crown；谓语 sits；on top of their head 是位置。crown 是头上的结构，head 是所在部位。","listen":"Q34 别把题干已有的 head 当答案；听辨 crown /kraʊn/ 的 /kr/ 起音和 /aʊ/。","questions":[34]},{"id":"seahorses-s7","section":"身体特征","en":"For movement, they rely on their dorsal and pectoral fins.","zh":"在运动方面，它们依靠背鳍和胸鳍。","note":"For movement 为话题状语；主干 they rely on their fins；dorsal / pectoral 是并列修饰语。","listen":"不必拼写每个生僻词；抓 rely on 和 fins，避免影响下一题。","questions":[]},{"id":"seahorses-s8","section":"身体特征","en":"They use their snout to catch food, and their favourite prey is shrimp.","zh":"它们用吻部捕食，最喜欢的猎物是虾。","note":"use A to do B 表示用途；and 连接两个分句；prey 作猎物总称，shrimp 是食物名称。","listen":"Q35 shrimp /ʃrɪmp/：开头 /ʃr/，结尾 /mp/；你原来写的 shrump 元音错误。","questions":[35]},{"id":"seahorses-s9","section":"繁殖过程","en":"In seahorse reproduction, the female places her eggs into the male's pouch.","zh":"在海马繁殖过程中，雌海马会把卵放入雄海马的育儿袋。","note":"主干 the female places her eggs；into the male's pouch 表示放入的位置。female / male 构成对照。","listen":"抓住 female → eggs → male's pouch 的顺序；pouch 是育儿袋。","questions":[]},{"id":"seahorses-s10","section":"繁殖过程","en":"Once they hatch, the young remain in the pouch for a period.","zh":"一旦孵化，幼体还会在育儿袋里停留一段时间。","note":"Once 引导时间状语从句；they 指前句的卵；the young 是幼体的集合表达；remain 表示继续停留。","listen":"once → hatch → remain 是时间链；不要把 hatch 误听成离袋。","questions":[]},{"id":"seahorses-s11","section":"繁殖过程","en":"During this time, the salt level is regulated to help them adjust to life in the ocean.","zh":"在此期间，盐度受到调节，以帮助幼体适应海洋生活。","note":"主干 the salt level is regulated，使用被动语态；to help… 表目的；adjust to 中 to 是介词。","listen":"Q36 抓 level 前的 salt /sɔːlt/；尾部 /lt/ 不能省略。不要凭中文意思拼成 soule。","questions":[36]},{"id":"seahorses-s12","section":"生存威胁","en":"Newborn seahorses face several challenges to survival.","zh":"新生海马会面临几种生存挑战。","note":"主干 newborn seahorses face challenges；newborn 修饰 seahorses；to survival 限定挑战涉及生存。","listen":"听到 challenges 即将进入威胁列表，准备区分自然威胁与人类威胁。","questions":[]},{"id":"seahorses-s13","section":"生存威胁","en":"They can be eaten by predators, or swept away by ocean currents.","zh":"它们可能被捕食者吃掉，也可能被洋流冲走。","note":"can be 后并列 eaten / swept away，两项都是被动；第二项省略 be；by 引出造成威胁的主体。","listen":"Q37 ocean currents：current 的本义之一是水流；currents /ˈkʌrənts/ 要保留复数 /s/。","questions":[37]},{"id":"seahorses-s14","section":"生存威胁","en":"Among human-related dangers, fishing poses the greatest threat.","zh":"在人类造成的危险中，捕捞构成最大的威胁。","note":"Among… 限定比较范围；主干 fishing poses the greatest threat；poses a threat 是构成威胁。","listen":"Q38 greatest 是最高级定位词；在 human-related 范围内找 fishing，而不是回填自然威胁 currents。","questions":[38]},{"id":"seahorses-s15","section":"圈养与保护","en":"In captivity, many seahorses struggle due to stress, which has been a major cause of low survival rates.","zh":"在圈养环境中，许多海马因应激而难以生存，而应激一直是存活率低的主要原因。","note":"主干 many seahorses struggle due to stress；which 引出对 stress 的补充说明；due to 后接原因。","listen":"Q39 due to 后等待原因 stress；结合语境译为应激，而不只是日常的压力。","questions":[39]},{"id":"seahorses-s16","section":"圈养与保护","en":"However, captive breeding programmes have helped lower the risk of disease.","zh":"不过，圈养繁殖计划已帮助降低了疾病风险。","note":"However 表转折；主干 programmes have helped lower the risk；help + 动词原形；of disease 限定风险类型。","listen":"Q40 disease /dɪˈziːz/，中间 /z/、重读 /iː/；注意拼写 dis-ease，区别复数 diseases。","questions":[40]}],"organic":[{"id":"organic-s1","section":"定义与引入","en":"Good morning.","zh":"大家早上好。","note":"简短问候语，用于正式展示的开场。","listen":"建立说话人的语速，不需要逐字记笔记。","questions":[]},{"id":"organic-s2","section":"定义与引入","en":"In today's presentation, I will talk about organic farming.","zh":"在今天的展示中，我将谈论有机农业。","note":"主干 I will talk about organic farming；In today's presentation 是范围状语。","listen":"talk about 后是主题；organic farming 的重音集中在 organic 的第二音节。","questions":[]},{"id":"organic-s3","section":"定义与引入","en":"Organic farming is an alternative agricultural system which originated early in the 20th century in reaction to rapidly changing farming practices.","zh":"有机农业是一种替代性的农业体系，起源于20世纪初，是对迅速变化的农业实践的回应。","note":"主干 Organic farming is an alternative agricultural system；which originated… 修饰 system；in reaction to 表示回应。","listen":"长句先抓 system / originated / in reaction to；不要因年代信息漏听核心定义。","questions":[]},{"id":"organic-s4","section":"定义与引入","en":"It is a method of crop and livestock production that involves much more than choosing not to use pesticides, fertilizers, genetically modified organisms and antibiotics.","zh":"它是一种作物和畜牧生产方法，其内容远不止选择不使用农药、化肥、转基因生物和抗生素。","note":"that involves… 修饰 method；much more than 强调不止于；choosing not to use 是动名词短语，其中 not 否定 use。","listen":"more than 后是被扩展的定义；四个名词组成列表，先识别类别，别被生词打断。","questions":[]},{"id":"organic-s5","section":"优势","en":"Why do we adopt organic farming?","zh":"我们为什么采用有机农业？","note":"Why 引导疑问句；adopt 表采用方法，而不是 adapt 适应。","listen":"设问提示进入 advantages 部分。","questions":[]},{"id":"organic-s6","section":"优势","en":"There are many advantages of it.","zh":"它有许多优点。","note":"There are 为存在句；it 回指 organic farming。","listen":"advantages 是列举优点的路标，准备依次定位31–34。","questions":[]},{"id":"organic-s7","section":"优势","en":"To begin with, organic farming is labelled as sustainable because it can protect the environment and maintain biological diversity.","zh":"首先，有机农业被称为可持续的，因为它能够保护环境并维持生物多样性。","note":"主干 organic farming is labelled as sustainable；because 后给原因；protect / maintain 为并列谓语。","listen":"Q31 labelled as 后是定性词 sustainable；与 protect / maintain 的因果关系一起记。","questions":[31]},{"id":"organic-s8","section":"优势","en":"It's also rewarding that more and more customers tend to buy organic food nowadays.","zh":"如今，越来越多的顾客倾向于购买有机食品，这也令人欣慰。","note":"It 作形式主语；that 从句为实际主语；tend to do 表倾向于做。rewarding 此处指令人感到欣慰。","listen":"also 提示另一优势；customers → buy 为下一句 sales 铺垫。","questions":[]},{"id":"organic-s9","section":"优势","en":"Product taste, concerns for the environment and the desire to avoid foods from genetically engineered organisms are among the many reasons some consumers prefer to buy organic food products.","zh":"产品口味、对环境的关切以及避免转基因食品的愿望，都是一些消费者偏好有机食品的原因。","note":"三个并列名词短语作主语，谓语 are；the desire to avoid… 是第三项；reasons 后省略 why。","listen":"长主语分为 taste / concerns / desire 三块；先听到 reasons 再判断购买动机。","questions":[]},{"id":"organic-s10","section":"优势","en":"So this type of farming is expected to contribute to an increase in sales for grocery stores globally.","zh":"因此，这种农业方式预计会促进全球食品杂货店销售额的增长。","note":"主干 this type of farming is expected to contribute；contribute to + 名词；an increase in sales 中 sales 是增长的对象。","listen":"Q32 increase in sales → enhance sales；globally → worldwide。题干要的是销售额，不是食品 foods。","questions":[32]},{"id":"organic-s11","section":"优势","en":"Most studies suggest that organic farming uses significantly less energy than conventional one.","zh":"大多数研究表明，有机农业使用的能源明显少于传统农业。","note":"suggest 后接 that 宾语从句；less…than 表比较；one 代指传统农业体系。表达练习可写 conventional farming，使指代更自然。","listen":"Q33 less energy 是核心；less 修饰不可数名词，听完比较双方。","questions":[33]},{"id":"organic-s12","section":"优势","en":"This is primarily due to the fact that organic farming eliminates the need for synthetic fertilizers, which require substantial energy for production.","zh":"这主要是因为有机农业免去了使用合成化肥的需要，而生产合成化肥需要大量能源。","note":"due to the fact that 引出原因；which require… 补充说明 fertilizers；主干 organic farming eliminates the need。","listen":"按此前录音核对采用 synthetic fertilizers。energy 是答案；fertilizers 是生产时消耗能源的对象。","questions":[33]},{"id":"organic-s13","section":"优势","en":"In organic farming, soil fertility is maintained through the recycling of organic residues and nutrients produced on the farm.","zh":"在有机农业中，土壤肥力通过回收利用农场产生的有机残余物和养分来维持。","note":"主干 soil fertility is maintained；through 表方式；produced on the farm 是过去分词短语，后置修饰前面的物质。","listen":"soil fertility 是主题词；maintained / recycling 共同表达维持肥力的办法。","questions":[]},{"id":"organic-s14","section":"优势","en":"This practice not only reduces energy consumption but also benefits the soil by promoting its health and abundance of organic nutrients.","zh":"这种做法不仅减少能源消耗，还通过改善土壤健康、增加有机养分使土壤受益。","note":"not only…but also… 连接 reduces / benefits 两个谓语；by + doing 表方式。","listen":"not only 后一项、but also 后另一项，听清两种好处。","questions":[]},{"id":"organic-s15","section":"优势","en":"Importantly, organic methods have the potential to effectively control insects that pose threats to crops, unlike artificial fertilizers which may not have the same level of efficacy.","zh":"有机方法有潜力有效控制威胁作物的昆虫；讲稿将其与可能没有同样效力的人造化肥作了对比。","note":"主干 organic methods have the potential；that pose threats… 修饰 insects。原稿把肥料与虫害控制作比较，逻辑不严谨；用于语言理解，不将其概括为农业事实。","listen":"Q34 reduce the number of → control；that / which may attack crops → pose threats to crops。答案用复数 insects。","questions":[34]},{"id":"organic-s16","section":"优势","en":"For example, a common practice in organic farming to control aphids, which are pests that can damage crops, is the introduction of ladybugs into the fields.","zh":"例如，有机农业控制蚜虫的一种常见做法，是把瓢虫引入田间；蚜虫是会损害作物的害虫。","note":"主干 a common practice is the introduction of ladybugs；to control aphids 表用途；which… 解释 aphids；that can damage… 修饰 pests。","listen":"先跳过插入的 which 从句，听出 practice → introduction of ladybugs 的主干。","questions":[]},{"id":"organic-s17","section":"优势","en":"Ladybugs are natural predators of aphids and feed on them, effectively reducing their population.","zh":"瓢虫是蚜虫的天敌，以蚜虫为食，从而有效减少其数量。","note":"主语 Ladybugs，谓语 are / feed；them 和 their 指蚜虫；reducing… 是结果状语。","listen":"feed on 是以……为食；reducing 后说的是蚜虫数量，别混淆两种昆虫。","questions":[]},{"id":"organic-s18","section":"优势","en":"This method is environmentally friendly and avoids the use of synthetic pesticides.","zh":"这种方法对环境友好，并避免使用合成农药。","note":"is / avoids 是并列谓语；synthetic pesticides 指合成农药，区别前面的 synthetic fertilizers。","listen":"fertilizers 肥料 / pesticides 农药分开记；不要把33题因果句中的对象替换掉。","questions":[]},{"id":"organic-s19","section":"产量与销售","en":"There are of course some disadvantages of organic farming.","zh":"当然，有机农业也有一些缺点。","note":"There are 为存在句；of course 为插入性的语气表达。","listen":"disadvantages 标记转向，准备听不利变化和数字。","questions":[]},{"id":"organic-s20","section":"产量与销售","en":"This past winter, due to extreme weather condition, the production of potatoes in the north of our country had gone down by 40%.","zh":"刚过去的冬天，由于极端天气，我国北部的土豆产量下降了40%。","note":"主干 the production of potatoes had gone down；due to… 表原因；by 40% 表降幅。原稿 condition 单数不自然，迁移表达宜用 extreme weather conditions。","listen":"Q35 potatoes /pəˈteɪtəʊz/ 要复数。down by 40% 是下降40%，不是降至40%。","questions":[35]},{"id":"organic-s21","section":"产量与销售","en":"Lots of farmers had to face the severe loss in the production.","zh":"许多农民不得不面对严重的减产损失。","note":"had to do 表过去不得不做；face 为面对；the severe loss 是宾语。","listen":"loss 解释上一句减产的后果，无需另等一个数字。","questions":[]},{"id":"organic-s22","section":"产量与销售","en":"The top 10 organic company in this country, Winterwild Production, just announced that their sales have been really slow because of the natural disasters.","zh":"讲稿说，该国排名前十的有机企业之一 Winterwild Production 刚宣布，其销售增长因自然灾害而十分缓慢。","note":"主干 company announced that…；公司名为同位语；原稿 the top 10 organic company 不规范，改写可用 one of the top ten organic companies。","listen":"专名只是定位点；sales slow 不等于销售额减少，要继续听后面的增长数字。","questions":[36]},{"id":"organic-s23","section":"产量与销售","en":"In the past, the sales might increase by 30%.","zh":"过去，销售额可能增长30%。","note":"主干 the sales might increase；by 30% 为增长幅度。","listen":"Q36 第一个数字30%是过去的增长率，先暂存，不立即作答。","questions":[36]},{"id":"organic-s24","section":"产量与销售","en":"But this year, it's only gone up by 20%.","zh":"但今年，销售额只增长了20%。","note":"it's = it has；gone up 表增加；But / only 限定今年的较小增长。","listen":"Q36 30% − 20% = 10 个百分点；按题目答案记10%。销售额仍在增长，只是增速变慢。","questions":[36]},{"id":"organic-s25","section":"产量与销售","en":"Despite weather challenges, the production of organic grass has not changed much over the years due to the implementation of various strategies.","zh":"尽管有天气带来的挑战，由于采取了多种策略，有机草的产量多年来没有太大变化。","note":"Despite 后接名词短语；主干 the production has not changed much；due to 解释原因。","listen":"Q37 has not changed much → remains the same；grass 是不可数名词，填 grass。","questions":[37]},{"id":"organic-s26","section":"产量与销售","en":"These include the use of resilient crop varieties that are carefully selected for their ability to withstand varying climatic conditions, the adoption of sustainable farming practices that prioritize soil health and fertility, and the incorporation of innovative irrigation and water management techniques.","zh":"这些策略包括使用能适应不同气候条件的抗逆作物品种、采用重视土壤健康和肥力的可持续农业方法，以及引入创新的灌溉与水管理技术。","note":"include 后三个并列宾语：the use / the adoption / the incorporation；两个 that 从句各自修饰前面的名词。","listen":"极长列举句分三块听：品种 → 农法 → 水管理；主干 These include…，不逐词硬译。","questions":[]},{"id":"organic-s27","section":"印度案例","en":"In the 1950s, organic farming in India experienced several changes.","zh":"20世纪50年代，印度的有机农业经历了几项变化。","note":"时间状语 In the 1950s；主干 organic farming experienced changes；in India 限定地点。","listen":"Q38 时间和地点是定位信号，准备逐项核对A/B/C。","questions":[38]},{"id":"organic-s28","section":"印度案例","en":"One notable development was the growing production of crops through organic farming practices, especially when compared to the early days when there was a food crisis.","zh":"一个显著的发展是，通过有机农业方法实现的作物产量增长，尤其是与早期发生粮食危机时相比。","note":"主干 One development was the growing production；through 表方式；when compared… 为省略结构；末尾 when 引出过去的时期。","listen":"Q38 growing production → yielded more crops，支持A。不能仅因听到 instructions 就选C。","questions":[38]},{"id":"organic-s29","section":"印度案例","en":"This positive outcome encouraged farmers to explore and adopt organic methods.","zh":"这一积极结果鼓励农民探索和采用有机方法。","note":"encourage sb to do；explore / adopt 并列。This positive outcome 回指产量增长。","listen":"positive outcome 继续支持前面A的结果，不是说所有技术都已成功实施。","questions":[38]},{"id":"organic-s30","section":"印度案例","en":"Unlike the common perception that farmers were unwilling to accept organic farming, they actually showed interest in its potential benefits.","zh":"与农民不愿接受有机农业这一普遍看法不同，他们实际上对其潜在好处表现出了兴趣。","note":"主干 they showed interest；Unlike 引出被对比的看法；that farmers were unwilling… 说明 perception 的内容。","listen":"Q38 unlike / actually 推翻“不愿接受”，排除B。听到 unwilling 不能断章取义。","questions":[38]},{"id":"organic-s31","section":"印度案例","en":"However, despite their enthusiasm, farmers faced challenges in successfully implementing organic farming techniques.","zh":"然而，尽管农民热情很高，他们在成功实施有机农业技术时仍面临挑战。","note":"However 转折；despite 后是名词；主干 farmers faced challenges；in implementing… 表具体困难。","listen":"Q38 有兴趣 ≠ 实施成功。However 后的困难是排除C的关键。","questions":[38]},{"id":"organic-s32","section":"印度案例","en":"They encountered difficulties in effectively applying the prescribed instructions, which hindered their ability to fully embrace organic farming practices.","zh":"他们在有效执行规定指导时遇到了困难，这阻碍了他们全面采用有机农业方法。","note":"encounter difficulties in doing；which 补充说明前面的困难造成的后果；hinder 表阻碍。","listen":"Q38 difficulties / hindered 否定“照说明就成功”的C；你原来选C，是忽略了这些限制词。","questions":[38]},{"id":"organic-s33","section":"国际综述","en":"In the 1990s, the United Nations World Food Programme published an international review on organic farming practices.","zh":"讲稿说，20世纪90年代，联合国世界粮食计划署发表了一份关于有机农业实践的国际综述。","note":"主干机构名 + published + a review；on 表主题。机构与年代按听力稿理解，此页不作历史事实核查。","listen":"Q39 review 是定位词；不要把“各国感兴趣”误当综述结论。","questions":[39]},{"id":"organic-s34","section":"国际综述","en":"The review examined the global implications of organic methods, concluding that such practices, which avoid synthetic chemicals, provide a sanctuary for wildlife, thereby enhancing biodiversity and ecological health.","zh":"该综述考察了有机方法的全球影响，并得出结论：这些避免使用合成化学品的方法为野生动物提供庇护，从而改善生物多样性和生态健康。","note":"主干 The review examined…；concluding that 引出结论；which… 插入解释 practices；thereby + doing 表结果。","listen":"Q39 concluding 后锁定结论：sanctuary for wildlife → benefits to wildlife，选C。","questions":[39]},{"id":"organic-s35","section":"国际综述","en":"Following the publication, an increased number of countries began showing interest in these findings.","zh":"综述发表后，越来越多的国家开始对这些发现表现出兴趣。","note":"Following 作介词，意为在……之后；主干 countries began showing interest；findings 指研究发现。","listen":"Q39 这是发表后的反应，不是 review 的结论，不能因此选A。","questions":[39]},{"id":"organic-s36","section":"国际综述","en":"Subsequently, many took steps to improve their agricultural practices, integrating organic farming principles to support both the environment and local economy.","zh":"随后，许多国家采取措施改进农业实践，将有机农业原则融入其中，以支持环境和当地经济。","note":"many 代指许多国家；take steps to do；integrating… 说明伴随做法；both…and… 并列。","listen":"Subsequently 推进时间；不要把后续行动与上句研究结论混为一谈。","questions":[]},{"id":"organic-s37","section":"未来与消费者","en":"As I have mentioned, compared to conventional farming, organic farming has its advantages and disadvantages.","zh":"如前所述，与传统农业相比，有机农业有其优点和缺点。","note":"As I have mentioned 为回顾；compared to… 为比较状语；主干 organic farming has…。","listen":"这是总结信号，准备听最终判断而不只抓前文环境优势。","questions":[]},{"id":"organic-s38","section":"未来与消费者","en":"Consumers' knowledge about organic food is increasing, so are their attitudes, preferences and willingness-to-pay for organic products.","zh":"消费者对有机食品的了解正在增加；讲稿也说，他们的态度、偏好和付费意愿在增强。","note":"so + 助动词 + 主语表示后者也如此；原稿把 attitudes 与 increase 搭配较生硬。可迁移为 Consumers are becoming more willing to pay for organic food。","listen":"consumers / preferences / willingness-to-pay 建立消费需求线索。","questions":[]},{"id":"organic-s39","section":"未来与消费者","en":"The good thing is that the scale of organic farming can be mostly determined by the demand of the market.","zh":"有利的一点是，有机农业的规模在很大程度上可以由市场需求决定。","note":"主干 The good thing is that…；can be determined 为被动；by the demand 指决定因素。","listen":"Q40 demand of the market → consumers，选A；mostly 不能擅自扩大成 entirely。","questions":[40]},{"id":"organic-s40","section":"未来与消费者","en":"Governments will respect people's attitude towards how they want their food to be produced.","zh":"政府会尊重人们对于食品生产方式的态度。","note":"主干 Governments will respect people's attitude；towards 后接 how 从句；want their food to be produced 是被动形式。","listen":"Q40 governments 虽被提及，但它们尊重消费者选择，不是独立决定规模，排除B。","questions":[40]},{"id":"organic-s41","section":"未来与消费者","en":"Of course, environmental protection should never stop however agriculture is developed in the future.","zh":"当然，无论未来农业如何发展，环境保护都不应停止。","note":"主干 environmental protection should never stop；however 引导让步，意为无论如何。","listen":"Q40 这是补充原则，并未说 nature 决定规模，排除C。","questions":[40]},{"id":"organic-s42","section":"未来与消费者","en":"What I'm going to share next is …","zh":"接下来我要分享的是……","note":"What 从句作主语，is 后内容尚未展开；它是过渡句。","listen":"末尾省略号保留，表示这部分录音在此转入下一话题。","questions":[]}]},"questions":{"seahorses":[{"n":31,"prompt":"These environments included stretches of ____ water.","answer":"shallow","original":"shallow","sentence":3,"why":"water 前需要形容词；shallow water 表浅水。","trap":"原来答对；保留形容词+名词语块。","wrong":false},{"n":32,"prompt":"Vegetation included a specific kind of ____.","answer":"grass","original":"grass","sentence":3,"why":"such as 后引出植被例子 grass。","trap":"原来答对；grass 不可数。","wrong":false},{"n":33,"prompt":"They have skin that stretches over bony ____.","answer":"plates","original":"plates","sentence":5,"why":"bony 后填名词 plates；骨板有多块，用复数。","trap":"原来答对；复数-s要保留。","wrong":false},{"n":34,"prompt":"A distinctive ____ sits on top of their head.","answer":"crown","original":"head","sentence":6,"why":"要填头上的冠状结构 crown；head 是它所在的部位。","trap":"定位对象混淆：头≠头冠。原记录 head→crown。","wrong":true},{"n":35,"prompt":"Their favourite prey is ____.","answer":"shrimp","original":"shrump","sentence":8,"why":"prey 后说明食物是虾 shrimp。","trap":"拼写：shrimp 中间是 i，不是 u；/ʃrɪmp/。","wrong":true},{"n":36,"prompt":"The ____ level is regulated inside the pouch.","answer":"salt","original":"soule","sentence":11,"why":"被调节的是 salt level，即盐度。","trap":"辨音与拼写：salt 的 /ɔː/ 和尾部 /lt/。","wrong":true},{"n":37,"prompt":"They can be swept away by ocean ____.","answer":"currents","original":"carr","sentence":13,"why":"swept away by ocean currents 表被洋流冲走。","trap":"词汇识别+复数：current /ˈkʌrənt/；答案 currents。","wrong":true},{"n":38,"prompt":"Among human-related dangers, ____ poses the greatest threat.","answer":"fishing","original":"未填","sentence":14,"why":"最高级 greatest 定位最大人类威胁 fishing。","trap":"漏答：没听清先标记继续，不在上一空停留。","wrong":true},{"n":39,"prompt":"In captivity, many seahorses struggle due to ____.","answer":"stress","original":"未填","sentence":15,"why":"due to 后的原因是 stress，即应激。","trap":"原因定位：due to / cause 都可提示答案。","wrong":true},{"n":40,"prompt":"Captive breeding programmes have helped lower the risk of ____.","answer":"disease","original":"deases","sentence":16,"why":"the risk of disease 表疾病风险。","trap":"拼写：disease，不是 deases。末尾-z与-s字母不同。","wrong":true}],"organic":[{"n":31,"prompt":"Organic farming is labelled as ____.","answer":"sustainable","original":"sustainable","sentence":7,"why":"labelled as sustainable 给出直接定性；后接环境与多样性的原因。","trap":"原来答对；sustainable可作方法、发展方式的形容词。","wrong":false},{"n":32,"prompt":"Enhance ____ in the grocery section for stores worldwide.","answer":"sales","original":"foods","sentence":10,"why":"an increase in sales → enhance sales；globally → worldwide。","trap":"题干理解：要填提升的指标，不是销售的商品 foods。","wrong":true},{"n":33,"prompt":"Save necessary ____ in producing fertilizers.","answer":"energy","original":"未填","sentence":12,"why":"less energy 与 require substantial energy 对应节能；合成化肥的生产需要大量能源。","trap":"长句抓因果：fertilizers 是生产对象，energy 是节省的资源。","wrong":true},{"n":34,"prompt":"Reduce the number of ____ which may attack crops.","answer":"insects","original":"未填","sentence":15,"why":"control insects that pose threats to crops → 减少危害作物的昆虫。","trap":"同义替换 control / reduce the number of；insects 为复数。","wrong":true},{"n":35,"prompt":"The yield of ____ went down by 40%.","answer":"potatoes","original":"potato","sentence":20,"why":"原句 the production of potatoes…had gone down by 40%。","trap":"单复数：potato 的复数为 potatoes，不能只写 potato。","wrong":true},{"n":36,"prompt":"Winterwild Production: the increase in sales is ____ lower than it used to be.","answer":"10%","original":"未填","sentence":24,"why":"过去增30%，今年增20%；题目接受10% / 10 percent。准确数学表述是增速低10个百分点。","trap":"要做减法；不是填20%或30%，也不是销售额下降10%。","wrong":true,"accepted":["10%","10 percent","10 per cent"]},{"n":37,"prompt":"Organic ____ production remains the same.","answer":"grass","original":"未填","sentence":25,"why":"the production of organic grass has not changed much → remains the same。","trap":"同义替换：未变化≈保持不变；grass不可数。","wrong":true},{"n":38,"prompt":"What happened to organic farming in India in the 1950s?","answer":"A","original":"C","sentence":28,"why":"growing production of crops 支持A。农民有兴趣但实施遇到困难。","trap":"B被 unlike / actually 推翻；C被 challenges / difficulties / hindered 推翻。","wrong":true,"options":["It yielded more crops.","Farmers were reluctant to accept it.","Farmers could apply organic farming successfully by following the instructions."]},{"n":39,"prompt":"The international review's conclusion focuses on what?","answer":"C","original":"C","sentence":34,"why":"concluding that…provide a sanctuary for wildlife，对应保护野生动物。","trap":"“各国感兴趣”是发表后的反应，不是综述结论；未比较各国方法。","wrong":false,"options":["Whether people are interested in organic farming.","Comparing different methods of organic farming across countries worldwide.","The benefits of organic farming to wildlife."]},{"n":40,"prompt":"What does the speaker think is the future of organic farming?","answer":"A","original":"A","sentence":39,"why":"scale…determined by the demand of the market：市场需求对应消费者。","trap":"提到政府与环境不等于它们是决定因素；要跟住问的是未来规模。","wrong":false,"options":["It depends on consumers.","It depends on the government.","It depends on nature."]}]}};
